code_example:
#include <iostream>
#include <array>
constexpr int factorial(int n) { return (n == 0) ? 1 : n * factorial(n - 1); }
constexpr std::array<int, 6> factorials = {factorial(0), factorial(1), factorial(2), factorial(3), factorial(4), factorial(5)};
int main() {
  for (int i = 0; i < factorials.size(); ++i) {
    std::cout << factorials[i] << " ";
  }
  std::cout << std::endl;
  return 0;
}
